#!/usr/bin/env python3
"""python3 make_tables.py -> RESULTS.md. Reads only data/*.tsv (NA stays NA); every number in the tables comes from there (the one-line captions are written by hand in this script)."""
import csv, os
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')
def tsv(n): return list(csv.DictReader((l for l in open(f'{D}/{n}.tsv') if not l.startswith('#')), delimiter='\t'))
def table(head, rows): return '| ' + ' | '.join(head) + ' |\n|' + '---|' * len(head) + '\n' + '\n'.join('| ' + ' | '.join(map(str, r)) + ' |' for r in rows) + '\n'
R = tsv('runs'); f = lambda x: x if x not in ('', 'NA') else 'n/m'
out = ['# Results (generated by make_tables.py from data/*.tsv; n/m = not measured yet)\n', 'Box: 4 cores (Intel Xeon 2.10 GHz, 1 thread per core), 15 GB RAM, hg38. Details: README.md.\n']
def add(title, line, tab): out.append(f'## {title}\n\n{line}\n\n{tab}')
runs = lambda e: [r for r in R if r['experiment'] == e]
cols = ['data', 'pairs', 'tool', 'commit', 'wall s', 'map s', 'CPU s', 'peak GB', 'Gbp/hr', 'Gbp/core-hr', 'runs']
row = lambda r: [r['data'], r['pairs'], r['tool'], r['commit'], f(r['wall_s']), f(r['map_s']), f(r['cpu_s']), f(r['peak_GB']), f(r['Gbp_hr']), f(r['Gbp_core_hr']), r['reps']]
add('Speed at 4 threads, 5M pairs from gz files', 'How fast lean-align maps 5M pairs on 4 cores, before and after the speed work. The minibwa rows are old and are being re-measured.', table(cols, [row(r) for r in runs('gz5m')]))
add('Large streamed runs (from the network, no disk)', 'Throughput stays flat from 10M to 40M pairs after the fix, and drops with run size before it. Peak memory is about 5.7 GB (the index is 5.3 GB).', table(cols, [row(r) for r in runs('stream')]))
add('Whole lanes (HiSeq 33.9M pairs, NovaSeq 40M pairs)', 'The slow-pair fix cuts wall time by 42 to 48 percent on both. minibwa on the same lane is not measured yet.', table(cols, [row(r) for r in runs('lane')]))
J = tsv('slow_jobs')
add('Slow jobs', 'Before the fix, one-minute jobs left cores idle for 39 to 50 percent of the run. After it, the longest job is about 1 s.', table(['data', 'build', 'jobs over 5 s', 'longest job s', '% of wall with fewer than 4 jobs running', 'wall over ideal s', 'core use incl. gunzip'], [[r[k] for k in ('data', 'build', 'jobs_over_5s', 'job_max_s', 'pct_wall_under_4_jobs', 'wall_over_ideal_s', 'core_use_pipeline')] for r in J]))
P = tsv('slow_pairs')
add('Slow pairs, mapped alone on 1 core (seconds)', 'The slowest single pairs, before and after. The SAM lines are identical in all three builds.', table(['pair', '64ae73f', '351301d', 'f465a57'], [[r['pair'], f(r['before_64ae73f']), f(r['fix1_351301d']), f(r['merged_f465a57'])] for r in P]))
S = tsv('slow_pairs_stream'); n1 = sum(float(r['before_ms']) >= 1000 for r in S); mx = max(float(r['after_ms']) for r in S)
add('Slow pairs inside the HiSeq lane run', f'{len(S)} pairs took one second or more before; the same pairs after the fix take at most {mx:.0f} ms. Classes: ' + ', '.join(f'{c} {sum(r["class"] == c for r in S)}' for c in sorted({r['class'] for r in S})) + '.', table(['pair', 'before ms', 'after ms', 'trimmed length mate 1/2', 'class'], [[r['pair'], r['before_ms'], r['after_ms'], f"{r['len1']}/{r['len2']}", r['class']] for r in S[:12]]) + f'\n(12 of {len(S)} rows shown; all rows in data/slow_pairs_stream.tsv.)\n')
A = tsv('accuracy'); g = lambda **k: next((r['value'] for r in A if all(r[a] == b for a, b in k.items())), 'n/m')
add('Real reads: proper and unique pairs against minibwa (% of all pairs)', 'lean-align gives up on more repetitive pairs than minibwa. "Unique" is our XU:Z:unique against minibwa MAPQ 60 on both mates. Measured on 027ef1e; later builds give identical output.', table(['dataset', 'proper: lean-align', 'proper: minibwa', 'unique: lean-align', 'unique: minibwa'], [[ds, g(block='real', dataset=ds, metric='pct_proper_pair', tool='lean-align'), g(block='real', dataset=ds, metric='pct_proper_pair', tool='minibwa'), g(block='real', dataset=ds, metric='pct_unique', tool='lean-align'), g(block='real', dataset=ds, metric='pct_unique', tool='minibwa')] for ds in ('novaseq_200k', 'hiseq_200k')]))
rows = [[m, r['class'], r['n_pairs'], g(block='sim', dataset=m, **{'class': r['class']}, metric='pct_pair_correct', tool='lean-align'), g(block='sim', dataset=m, **{'class': r['class']}, metric='pct_pair_correct', tool='minibwa')] for m in ('mason', 'low', 'high') for r in A if r['block'] == 'sim' and r['dataset'] == m and r['tool'] == 'lean-align']
add('Simulated reads: pairs placed correctly (%), by our class', 'Pairs we call unique are as correct as minibwa. Pairs we leave unknown or not proper are not placed, so they count as wrong for us.', table(['simulation', 'our class', 'pairs', 'lean-align', 'minibwa'], rows))
open(os.path.join(D, '..', 'RESULTS.md'), 'w').write('\n'.join(out))
